(window.webpackJsonp=window.webpackJsonp||[]).push([[23],{117:function(e){e.exports=JSON.parse('{"metadata":{"timed":true,"story ID":"ca8d329c-b803-44e0-bb4d-fb14ef208137","title":{"_default":"AAHP 073 Diana Bell 9-5-2009"},"media":{"audio":"","video":"https://www.youtube.com/watch?v=fK5S7dX0K-c"},"languages":[],"date_created":"","date_uploaded":"10/28/2026","source":{"_default":""},"description":"","genre":"","author":"","glosser":"","speakers":["Diana Bell","Matthew White"],"xml_file_name":"AAHP 073 Diana Bell 9-5-2009.eaf","source_filetype":"ELAN","tier IDs":{"Diana Bell":{"subdivided":false},"Interviewer":{"subdivided":false},"Features":{"subdivided":false}},"speaker IDs":{"S1":{"name":"Diana Bell","tier":"Diana Bell"},"S2":{"name":"Matthew White","tier":"Interviewer"},"S3":{"tier":"Features"}}},"sentences":[{"speaker":"S2","tier":"Interviewer","start_time_ms":0,"end_time_ms":2158,"num_slots":1,"text":"All right, I’m going to pull up a little closer.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":2158,"end_time_ms":5828,"num_slots":1,"text":"And we are recording.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":5828,"end_time_ms":8600,"num_slots":1,"text":"If you could repeat for me your name?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":8600,"end_time_ms":10636,"num_slots":1,"text":"Diana Clifton Bell.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":10636,"end_time_ms":13770,"num_slots":1,"text":"Okay. And how long- when did you attend the University of Florida?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":13770,"end_time_ms":22120,"num_slots":1,"text":"I attended the University of Florida uh from 1967 to 1969 as a undergrad.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":22120,"end_time_ms":28110,"num_slots":1,"text":"And I returned in 71, I received a master’s in 72.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":28110,"end_time_ms":29220,"num_slots":1,"text":"Okay, in what subjects?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":29220,"end_time_ms":41770,"num_slots":1,"text":"Uh. As an undergrad, I majored in Language Arts—English, as we called it then— Education, and my master’s program um involved Special Education.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":41770,"end_time_ms":45565,"num_slots":1,"text":"Uh. I received a master’s in Mental Retardation.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":45565,"end_time_ms":49975,"num_slots":1,"text":"Okay. Um and so, could one assume, then, that you worked with the Education school?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":49975,"end_time_ms":51855,"num_slots":1,"text":"Yes. I was a teacher.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":51855,"end_time_ms":56645,"num_slots":1,"text":"Okay. Um and um where are you from-where were you from when you went to school?","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":56645,"end_time_ms":58149,"num_slots":1,"text":"We’ll start with that.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":58149,"end_time_ms":59647,"num_slots":1,"text":"I’m from Daytona Beach, Florida.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":59647,"end_time_ms":60265,"num_slots":1,"text":"Do you still live there?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":60265,"end_time_ms":60675,"num_slots":1,"text":"Yes.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":60675,"end_time_ms":62340,"num_slots":1,"text":"And you went right back to Daytona Beach.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":62340,"end_time_ms":66910,"num_slots":1,"text":"I didn’t go uh back immediately, but eventually I went back.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":66910,"end_time_ms":74742,"num_slots":1,"text":"Okay. Um and uh if you could first for just a moment, in sort of a general way, reflect um your experiences at UF.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":74742,"end_time_ms":79548,"num_slots":1,"text":"It sounds like you were here for —I didn’t do the math in my head; about four years, sounds standard.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":79548,"end_time_ms":89075,"num_slots":1,"text":"Yeah, uh, yes. Uh I-I got my —well, I did my undergrad in—well, I came here as a junior college transfer.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":89075,"end_time_ms":90185,"num_slots":1,"text":"Oh, okay. From where?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":90185,"end_time_ms":91125,"num_slots":1,"text":"From Daytona Beach.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":91125,"end_time_ms":94525,"num_slots":1,"text":"I went to uh Daytona Beach Junior College at the time.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":94525,"end_time_ms":100578,"num_slots":1,"text":"I came here as a junior in- in 67, and I graduated in 69.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":100578,"end_time_ms":108145,"num_slots":1,"text":"Okay. Now, that-that strikes me as-as an American generalist, that’s a very interesting time in American educational history um for colleges.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":108145,"end_time_ms":116625,"num_slots":1,"text":"What were your experiences here at UF, um both as part of the general population, but also as an African American student?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":116625,"end_time_ms":129521,"num_slots":1,"text":"Um as- in general, the late 60s was um a very um, shall I say turbulent time in our history?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":129521,"end_time_ms":161271,"num_slots":1,"text":"Um a time of social unrest um, um, a lot with the new uh era of thinking in terms of the whole free love scene, and the-the uh drug culture, and of course uh Civil Rights was a very big thing uh for me, being an African American— and in fact for the country, because it meant a lot um of changes, and a great challenge for the country.","dependents":[]},{"speaker":"S3","tier":"Features","start_time_ms":129521,"end_time_ms":161271,"num_slots":1,"text":"AAOH Feature: Person/num. agreement","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":161271,"end_time_ms":167180,"num_slots":1,"text":"Now, what activities uh —now, that’s America, but what activities were here at University of Florida?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":167180,"end_time_ms":180581,"num_slots":1,"text":"Well um, at the University of Florida uh, there were a lot of activities, most of which I felt uh excluded from ?","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":180581,"end_time_ms":182301,"num_slots":1,"text":"Give me an example.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":182301,"end_time_ms":184427,"num_slots":1,"text":"The sororities.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":184427,"end_time_ms":185172,"num_slots":1,"text":"Mhm.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":185172,"end_time_ms":196567,"num_slots":1,"text":"Um uh...and just, there were no organizations that I received invitations to join.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":196567,"end_time_ms":200379,"num_slots":1,"text":"Um but I really wasn’t worried about it.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":200379,"end_time_ms":204782,"num_slots":1,"text":"Um and I didn’t seek to join.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":204782,"end_time_ms":216967,"num_slots":1,"text":"Um I think I was a little bit sensitive, and I felt like, “Okay, you’re going there, you going to get an education, and you’re not going to really worry about pushing the envelope.”","dependents":[]},{"speaker":"S3","tier":"Features","start_time_ms":204791,"end_time_ms":216967,"num_slots":1,"text":"AAOH Feature: Null copula","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":216967,"end_time_ms":219827,"num_slots":1,"text":"You know, just do what you have to do.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":219827,"end_time_ms":223757,"num_slots":1,"text":"But uh I must say uh, it was a very pleasant experience for me.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":223757,"end_time_ms":230447,"num_slots":1,"text":"Um uh I came as the daughter of two parents who had not finished high school.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":230447,"end_time_ms":233269,"num_slots":1,"text":"And I was the oldest in my family .","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":233269,"end_time_ms":236617,"num_slots":1,"text":"And I had relatives here, and I was happy to be here.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":236617,"end_time_ms":237557,"num_slots":1,"text":"Relatives in Gainesville?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":237557,"end_time_ms":240877,"num_slots":1,"text":"Yes, yes. And I was happy to be here.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":240877,"end_time_ms":248572,"num_slots":1,"text":"So. Um you know, even though I felt like things were not exactly open to me, I was not unhappy about it.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":248572,"end_time_ms":262167,"num_slots":1,"text":"Um I uh was um a member of a very small group of Black students that were here at the time, and we set about creating a place for ourselves, you know.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":262167,"end_time_ms":270367,"num_slots":1,"text":"Um and we uh established the first Black Student Union um in my junior year, my first year here.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":270367,"end_time_ms":284553,"num_slots":1,"text":"And that was something that um I became very involved in, um bringing um national Black figures here to speak to uh the city and students about issues that were coming up.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":284553,"end_time_ms":286476,"num_slots":1,"text":"Do you remember any of them, the names, the—?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":286476,"end_time_ms":288207,"num_slots":1,"text":"Adam Clayton Powell.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":288207,"end_time_ms":294546,"num_slots":1,"text":"And um I believe um um... Muhammad Ali.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":294546,"end_time_ms":299488,"num_slots":1,"text":"Um I believe-I believe I remember him coming.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":299488,"end_time_ms":303454,"num_slots":1,"text":"He was just getting started with the boxing and everything.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":303454,"end_time_ms":305571,"num_slots":1,"text":"That was an interesting time for his life, too.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":305571,"end_time_ms":306321,"num_slots":1,"text":"Yes, yes.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":306321,"end_time_ms":307642,"num_slots":1,"text":"That must have been fascinating.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":307642,"end_time_ms":309637,"num_slots":1,"text":"I remember it was, it was fascinating.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":309637,"end_time_ms":310528,"num_slots":1,"text":"Was he an interesting —?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":310528,"end_time_ms":313603,"num_slots":1,"text":"Well, he was pretty .","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":313603,"end_time_ms":316773,"num_slots":1,"text":"And he was talking to— both—","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":316773,"end_time_ms":318493,"num_slots":1,"text":"Yeah; full disclosure, he’s one of my favorite people.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":318493,"end_time_ms":330148,"num_slots":1,"text":"Yeah. Yeah, and at the time, he wasn\'t-he hadn’t become uh really uh known for his defiance of the things that he saw you know as immoral.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":330148,"end_time_ms":332593,"num_slots":1,"text":"But he was just starting his career .","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":332593,"end_time_ms":335073,"num_slots":1,"text":"He was loud, and he was promoting himself.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":335073,"end_time_ms":343493,"num_slots":1,"text":"But um he was still a figure that was saying something, and someone to- that you wanted to know, “What is this person all about ?”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":343493,"end_time_ms":348303,"num_slots":1,"text":"But I think Adam Clayton Powell was the most prominent people-person that I remember.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":348303,"end_time_ms":366453,"num_slots":1,"text":"Um I -um I was, so I think I was more of a voyeur uh on the campus scene in terms of all the things that were happening, the sit-in at Tigert Hall, or the takeover of Tigert Hall by the Black students","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":366453,"end_time_ms":367923,"num_slots":1,"text":"Now, I’ve heard of that. What was that all about?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":367923,"end_time_ms":369083,"num_slots":1,"text":"—my senior year.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":369083,"end_time_ms":375273,"num_slots":1,"text":"Um well, they-they felt that-that Tigert was not responsive to the needs of Black students .","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":375273,"end_time_ms":382299,"num_slots":1,"text":"And um so, they were going to sit in until certain demands were made .","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":382299,"end_time_ms":401753,"num_slots":1,"text":"And I-I don’t remember exactly what all the demands were, but I believe that uh establishing um Black um- Black culture courses um were—that-I-I think that was a part of the demand, to have some um Black history, or African—","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":401753,"end_time_ms":402724,"num_slots":1,"text":"And you didn’t participate in that.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":402724,"end_time_ms":403748,"num_slots":1,"text":"I didn’t participate .","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":403748,"end_time_ms":404098,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":404098,"end_time_ms":414538,"num_slots":1,"text":"I didn\'t participate and that was-that was um heavy on my mind, because I was not —of course I was sympathetic .","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":414538,"end_time_ms":427164,"num_slots":1,"text":"But by the same token, I felt like I couldn’t afford to put myself in a position to be thrown out of school, because so much was riding on me in terms of my family’s expectations.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":427164,"end_time_ms":431844,"num_slots":1,"text":"And so it was hard, it was hard for me.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":431844,"end_time_ms":432963,"num_slots":1,"text":"It was very hard.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":432963,"end_time_ms":437265,"num_slots":1,"text":"Now that’s uh uh, on a social level that’s interesting.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":437265,"end_time_ms":438760,"num_slots":1,"text":"What about scholastically?","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":438760,"end_time_ms":445274,"num_slots":1,"text":"Um what was it like to come to University of Florida as either just again a general or an African American student?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":445274,"end_time_ms":457129,"num_slots":1,"text":"Well, before I came, I received a lot of scary stories about how, “Oh, the courses are so hard; you’re not prepared; you’re going to fail ; blah blah blah blah blah blah. ”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":457129,"end_time_ms":463789,"num_slots":1,"text":"But um I had come from a um segregated school .","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":463789,"end_time_ms":468404,"num_slots":1,"text":"Um the whole system from grade one through twelve, I’d been with only Black kids.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":468404,"end_time_ms":479845,"num_slots":1,"text":"I had gone to junior college, where I was always only-the only Black student in there, but I had been raised in that segregated situation to think that I was very special.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":479845,"end_time_ms":485604,"num_slots":1,"text":"And that I was the cat’s meow, that I was-I was somebody !","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":485604,"end_time_ms":491890,"num_slots":1,"text":"And so, I really didn’t feel intimidated by what I was told.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":491890,"end_time_ms":492854,"num_slots":1,"text":"And I said—","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":492854,"end_time_ms":493824,"num_slots":1,"text":"Now, who was telling you this?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":493824,"end_time_ms":498174,"num_slots":1,"text":"Just other Black people, people in general.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":498174,"end_time_ms":503834,"num_slots":1,"text":"And I don’t know where they received their information from, but they felt like—well they felt like,","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":503834,"end_time_ms":508706,"num_slots":1,"text":"okay, they felt like my education was inferior because it was separate.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":508706,"end_time_ms":520747,"num_slots":1,"text":"And you know you used to get the old books, and-and really not a lot of financial support —not as much you know in terms of materials and all that as the other- as the predominantly White schools.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":520747,"end_time_ms":526374,"num_slots":1,"text":"So therefore, everyone concluded that the education was inferior.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":526374,"end_time_ms":528744,"num_slots":1,"text":"Okay this was Black students telling you this.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":528744,"end_time_ms":531284,"num_slots":1,"text":"These were mostly Black- mostly Black people telling me this.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":531284,"end_time_ms":532684,"num_slots":1,"text":"What about the teachers?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":532684,"end_time_ms":536651,"num_slots":1,"text":"The teachers always told me I could do whatever I wanted to do.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":536651,"end_time_ms":550561,"num_slots":1,"text":"But people just in the community felt like, “Oh, okay” —and I think they basically felt that because it was an all -White institution— that when I went in, I would be ostracized, I would be treated negatively, I would fail, I couldn’t measure up.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":550561,"end_time_ms":552780,"num_slots":1,"text":"But I never bought into it.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":552780,"end_time_ms":554250,"num_slots":1,"text":"And I said, “Well, we’ll see. ”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":554250,"end_time_ms":560088,"num_slots":1,"text":"And so, when I came, I really came with a lot of confidence and I-I never had any problems whatsoever.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":560088,"end_time_ms":567417,"num_slots":1,"text":"And even though I didn\'t feel a part of the social scene after class, like I said it didn\'t really bother me although I could see it.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":567417,"end_time_ms":573082,"num_slots":1,"text":"Um you know I did- I did fine in my classes.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":573082,"end_time_ms":578445,"num_slots":1,"text":"You know I-I wasn\'t the A student, but then I didn\'t work as hard as I could have.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":578445,"end_time_ms":588795,"num_slots":1,"text":"I just-I did-I did a little bit more partying than I should have, you know? So um-so I-I did, you know I did pretty well.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":588795,"end_time_ms":595447,"num_slots":1,"text":"And um I enjoyed my stay. And I was close to home- I could go home whenever I wanted.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":595447,"end_time_ms":602920,"num_slots":1,"text":"I had family in the community, so I could visit them as much as I wanted and- and it was a fine mix for me.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":602920,"end_time_ms":612200,"num_slots":1,"text":"Uh now, there\'s something that I experienced that I think was unique to my um generation the um housing situation.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":612200,"end_time_ms":621275,"num_slots":1,"text":"In the dormitory. Um there were three of us black girls in Rawlings Hall.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":621275,"end_time_ms":625725,"num_slots":1,"text":"One girl disclaimed being Black she-well she say she was a Puerto Rican.","dependents":[]},{"speaker":"S3","tier":"Features","start_time_ms":621275,"end_time_ms":625725,"num_slots":1,"text":"AAOH Feature: Person/num. agreement","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":625725,"end_time_ms":630450,"num_slots":1,"text":"So we said okay. So we used to call her the Black Puerto Rican. But that was an inside joke.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":630450,"end_time_ms":635005,"num_slots":1,"text":"Um my roommate um who at first had her own room and I had my own room.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":635005,"end_time_ms":637530,"num_slots":1,"text":"We didn\'t have roommates. All the other girls had roommates.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":637530,"end_time_ms":639158,"num_slots":1,"text":"At first we were all separate.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":639158,"end_time_ms":651860,"num_slots":1,"text":"Um the girl from Ocala Frankie Crosky and I met and decided we were going to become roommates and so second semester we petitioned to live together and so we did for that first year.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":651860,"end_time_ms":668655,"num_slots":1,"text":"Um if you-okay in the dormitory, no boys could come upstairs. They could only meet you downstairs in the um reception area. So you had a buzzer and they would buzz your room and tell you that such and such was down for you in the lobby.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":668655,"end_time_ms":673111,"num_slots":1,"text":"So you\'d have to walk down and receive them there and if- you know- if you went off, fine.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":673111,"end_time_ms":678491,"num_slots":1,"text":"If you went off campus, you had to be back by, I believe it was 12 o\' clock.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":678491,"end_time_ms":686141,"num_slots":1,"text":"If you weren\'t going to come back you had to sign out to some place in particular.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":686141,"end_time_ms":690956,"num_slots":1,"text":"Uh that was my junior year. My senior year- seniors were given a key.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":690956,"end_time_ms":694371,"num_slots":1,"text":"That was the first experimental year where they were given a key .","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":694371,"end_time_ms":703901,"num_slots":1,"text":"They could come in any time they wanted, and they could let themselves in the locked dormitory with their key, but they could not let anyone else in with their key.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":703901,"end_time_ms":709192,"num_slots":1,"text":"So, that’s when they first started to experiment with giving more freedom.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":709192,"end_time_ms":714501,"num_slots":1,"text":"Uh if you were a junior, you still had to check out, and you used to had to— otherwise be in by twelve .","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":714501,"end_time_ms":720105,"num_slots":1,"text":"Um I’m not sure when they stopped that, because I graduated in 69.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":720105,"end_time_ms":723381,"num_slots":1,"text":"You know, and when I came back, I wasn’t in the dormitories.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":723381,"end_time_ms":736521,"num_slots":1,"text":"But I think that was kind of unique, because when my daughter was here in 90-um, she came in 91, graduated in 95, the boys could come in; I know there were boys that spent the night.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":736521,"end_time_ms":745520,"num_slots":1,"text":"Uh I can remember going into the restroom, and a boy meeting me coming out, and I’m going, “Whoa!”","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":745520,"end_time_ms":746650,"num_slots":1,"text":"A lot of changes between 1969 and 1990.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":746650,"end_time_ms":750115,"num_slots":1,"text":"A lot of changes, very co-ed, very co-ed!","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":750115,"end_time_ms":752836,"num_slots":1,"text":"So that was, like, shocking to me.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":752836,"end_time_ms":754716,"num_slots":1,"text":"That was really interesting.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":754716,"end_time_ms":756926,"num_slots":1,"text":"Now, that brings up an interesting topic.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":756926,"end_time_ms":760126,"num_slots":1,"text":"You left for a few years and came back as a graduate student.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":760126,"end_time_ms":760556,"num_slots":1,"text":"Yes.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":760556,"end_time_ms":765962,"num_slots":1,"text":"Did you notice any differences, any changes, any evolution at all uh on campus?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":765962,"end_time_ms":768866,"num_slots":1,"text":"Well see, as a graduate student, you’re in a different world.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":768866,"end_time_ms":769683,"num_slots":1,"text":"Sure.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":769683,"end_time_ms":777961,"num_slots":1,"text":"Um I was not in touch with people who lived in dormitories, or-or really in touch with anyone that wasn’t in my department.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":777961,"end_time_ms":786101,"num_slots":1,"text":"And so, I was married by then, um and just living in a- a different world altogether.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":786101,"end_time_ms":787391,"num_slots":1,"text":"Part time, full time?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":787391,"end_time_ms":794491,"num_slots":1,"text":"I was full time, because I- I had uh been a teacher for two years, and I- I came back that third year","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":794491,"end_time_ms":800979,"num_slots":1,"text":"um deciding that I needed more to teach the students that I had.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":800979,"end_time_ms":818931,"num_slots":1,"text":"Because um in English education we- we’d been given um an approach to teaching that worked very well with bright students, but more and more special needs students were emerging, and I felt like, “Okay, I need something else. ”","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":818931,"end_time_ms":823096,"num_slots":1,"text":"Now, let me back up here: when you said they worked with—did you say “White” or “right? ”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":823096,"end_time_ms":824406,"num_slots":1,"text":"I didn’t say “White.”","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":824406,"end_time_ms":825806,"num_slots":1,"text":"Oh, I’m sorry.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":825806,"end_time_ms":829536,"num_slots":1,"text":"You said-You said, methods that worked some kind of student —","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":829536,"end_time_ms":830856,"num_slots":1,"text":"Oh, special needs.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":830856,"end_time_ms":832656,"num_slots":1,"text":"But before that, they worked for —","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":832656,"end_time_ms":833756,"num_slots":1,"text":"Oh, bright!","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":833756,"end_time_ms":835381,"num_slots":1,"text":"Bright! I\'m sorry!","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":835381,"end_time_ms":836956,"num_slots":1,"text":"Bright students. Bright students.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":836956,"end_time_ms":837727,"num_slots":1,"text":"My apologies.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":837727,"end_time_ms":838606,"num_slots":1,"text":"Right.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":838606,"end_time_ms":854411,"num_slots":1,"text":"You know, um analyzing uh poems, a lot of analytical kind of thing; um and through um- composition through analysis of character themes and that kind of stuff, which you still, it’s still doing in-in schools.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":854411,"end_time_ms":860411,"num_slots":1,"text":"But there-there are different stratas of kids that had needs that were different from that .","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":860411,"end_time_ms":871502,"num_slots":1,"text":"And I said, “Okay, what can I do to empower myself to-to gain additional skills to reach these students who are not there, but who are showing up in my class every day?”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":871502,"end_time_ms":877652,"num_slots":1,"text":"And so, I got the idea to go back and uh get a degree in Special Education.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":877652,"end_time_ms":881232,"num_slots":1,"text":"And so, that’s what um I received my master’s in.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":881232,"end_time_ms":885192,"num_slots":1,"text":"And so, I don’t really know what the- the setting was.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":885192,"end_time_ms":887194,"num_slots":1,"text":"So you weren’t involved in the Black Student Union, or —","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":887194,"end_time_ms":888772,"num_slots":1,"text":"No, not- not at that point.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":888772,"end_time_ms":897297,"num_slots":1,"text":"It was just, you know uh deal with my husband, and deal with my-my courses, and that was- that was my focus.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":897297,"end_time_ms":897885,"num_slots":1,"text":"You know?","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":897885,"end_time_ms":903172,"num_slots":1,"text":"Um let’s back up a little bit: uh you were talking about your parents, and they hadn’t even graduated —","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":903172,"end_time_ms":903822,"num_slots":1,"text":"From high school.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":903822,"end_time_ms":904272,"num_slots":1,"text":"High school.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":904272,"end_time_ms":911438,"num_slots":1,"text":"So if I could ask you to go back a little bit and talk about you know maybe your home life or early schooling; so, that’s a huge decision to go be the first.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":911438,"end_time_ms":913318,"num_slots":1,"text":"First family member to go to college.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":913318,"end_time_ms":913808,"num_slots":1,"text":"Right.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":913808,"end_time_ms":914808,"num_slots":1,"text":"In my immediate family.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":914808,"end_time_ms":918008,"num_slots":1,"text":"However, I had three aunts who were teachers.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":918008,"end_time_ms":922328,"num_slots":1,"text":"And so, they motivated me, you know—and my mom.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":922328,"end_time_ms":928273,"num_slots":1,"text":"Because my mom was a very smart lady despite the- the fact that she didn’t finish high school.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":928273,"end_time_ms":934793,"num_slots":1,"text":"Hers was more of a um… uh… I\'ve- you know she got married early.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":934793,"end_time_ms":946343,"num_slots":1,"text":"My dad came back from the war, and she was being raised by her grandparents, and um she felt like, “Okay, I need to- I need to make some money to take of myself.”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":946343,"end_time_ms":949483,"num_slots":1,"text":"Because it was hard times for the family in general.","dependents":[]},{"speaker":"S3","tier":"Features","start_time_ms":946343,"end_time_ms":949483,"num_slots":1,"text":"AAOH Feature: Existential it/dey","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":949483,"end_time_ms":955370,"num_slots":1,"text":"And my father came back from the war, and you know they fell in love, and they got married.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":955370,"end_time_ms":960752,"num_slots":1,"text":"And so, when he came back from the war, he uh wanted a trade.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":960752,"end_time_ms":974453,"num_slots":1,"text":"Then, uh it was- that was the big thing in Black families for the men to get trades, because they - the um—being a brick mason, or a carpenter and all that, paid some pretty good money.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":974453,"end_time_ms":979667,"num_slots":1,"text":"You know? And so, my father went to uh Bethune-Cookman College Trade School","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":979667,"end_time_ms":980669,"num_slots":1,"text":"I\'m sorry, where?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":980669,"end_time_ms":985483,"num_slots":1,"text":"Bethune-Cookman College Trade School and um- on the GI Bill.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":985483,"end_time_ms":993298,"num_slots":1,"text":"And so, he became um a brick mason, and later a subcontractor.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":993298,"end_time_ms":996828,"num_slots":1,"text":"So for thirty-eight years, he built houses.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":996828,"end_time_ms":1005968,"num_slots":1,"text":"But my mom- my mom worked for uh a prominent White family in town, um keeping their house and their- their children.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1005968,"end_time_ms":1009798,"num_slots":1,"text":"And so you know they made a very modest living.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1009798,"end_time_ms":1011962,"num_slots":1,"text":"They built our home.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1011962,"end_time_ms":1015868,"num_slots":1,"text":"Um I was one of four children.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1015868,"end_time_ms":1021054,"num_slots":1,"text":"They really preached education to all of us; however, I was the only one that went to college.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1021054,"end_time_ms":1026868,"num_slots":1,"text":"I thought I would be the beginning, but somewhere along the way, the others didn’t take to it.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1026868,"end_time_ms":1032711,"num_slots":1,"text":"But you know I’ve always been highly motivated for education—","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1032711,"end_time_ms":1033613,"num_slots":1,"text":"Yes.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1033613,"end_time_ms":1042488,"num_slots":1,"text":"And um I excelled you know coming through uh the different grades, and it just seemed like the normal progression for me.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1042488,"end_time_ms":1044064,"num_slots":1,"text":"So.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1044064,"end_time_ms":1048558,"num_slots":1,"text":"Now you mentioned that you were the only Black student in your junior college— class, is that correct?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1048558,"end_time_ms":1049125,"num_slots":1,"text":"Classes.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1049125,"end_time_ms":1049648,"num_slots":1,"text":"Classes.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1049648,"end_time_ms":1051568,"num_slots":1,"text":"So were the teachers encouraging to go on to—?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1052623,"end_time_ms":1053773,"num_slots":1,"text":"Were the teachers encouraging?","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1053773,"end_time_ms":1054603,"num_slots":1,"text":"Yeah. The teachers. You know to-?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1054603,"end_time_ms":1057887,"num_slots":1,"text":"No, the teachers-teachers didn’t say anything to me personal.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1057887,"end_time_ms":1060294,"num_slots":1,"text":"It was just, they taught their course.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1060294,"end_time_ms":1067677,"num_slots":1,"text":"You know they didn’t say anything good or bad, just taught the content.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1067677,"end_time_ms":1072728,"num_slots":1,"text":"And so, my reinforcement pretty much came from my family.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1072728,"end_time_ms":1081240,"num_slots":1,"text":"And my um teachers through the years you know always told me I was special, um always told me I was smart.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1081240,"end_time_ms":1098842,"num_slots":1,"text":"Um I was an uh honors student, um honor society, um I was in the campus leadership, um was a part of the band as one of those little flag girl sort of things, kind of a half-majorette, half-flag girl—","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1098842,"end_time_ms":1099432,"num_slots":1,"text":"Here at UF?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1099432,"end_time_ms":1100592,"num_slots":1,"text":"No, no, no, that was at —","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1100592,"end_time_ms":1101023,"num_slots":1,"text":"It’s junior high.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1101023,"end_time_ms":1101483,"num_slots":1,"text":"In high school.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1101483,"end_time_ms":1101835,"num_slots":1,"text":"In high school.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1101835,"end_time_ms":1102678,"num_slots":1,"text":"In high school.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1102678,"end_time_ms":1109132,"num_slots":1,"text":"So I was involved with a lot things that-that gave me a lot of uh self-assurance.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1109132,"end_time_ms":1117217,"num_slots":1,"text":"And so, I think that helped me to uh to come here and and just deal with things the way things were.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1117217,"end_time_ms":1122627,"num_slots":1,"text":"And I you know I love this place—I love Florida, I’m a Gator all the way.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1122627,"end_time_ms":1125777,"num_slots":1,"text":"So, let me ask this: what led you to come to the University of Florida?","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1125777,"end_time_ms":1127497,"num_slots":1,"text":"What was your decision-making there?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1127497,"end_time_ms":1133498,"num_slots":1,"text":"Um at first, I was thinking of going to Dillard in New Orleans, which is a Black school.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1133498,"end_time_ms":1134152,"num_slots":1,"text":"Uh-huh.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1134152,"end_time_ms":1136403,"num_slots":1,"text":"Purely because I wanted to go to Mardi Gras.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1136403,"end_time_ms":1137442,"num_slots":1,"text":"to what-do-you-call","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1137442,"end_time_ms":1140077,"num_slots":1,"text":"from the pictures at Mardi Gras.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1140077,"end_time_ms":1142372,"num_slots":1,"text":"And my parents didn’t know, I don’t think so.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1142372,"end_time_ms":1143828,"num_slots":1,"text":"Why not?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1143828,"end_time_ms":1150902,"num_slots":1,"text":"Well, they said- “That’s too far away, we don’t have uh the money to uh support you in that.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1150902,"end_time_ms":1154962,"num_slots":1,"text":"We- we can’t you know bring you home for the holidays.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1154962,"end_time_ms":1159822,"num_slots":1,"text":"Uh it’s too far for us to send for you if you know if there’s an emergency or whatever.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1159822,"end_time_ms":1162112,"num_slots":1,"text":"We think it’s better if you go to junior college.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1162112,"end_time_ms":1168221,"num_slots":1,"text":"And then, when you go to junior college, then you can go to one of the state schools, and that will be better for you and for us. ”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1168221,"end_time_ms":1175591,"num_slots":1,"text":"So, you know after uh really uh putting up a big fuss, I lost.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1175591,"end_time_ms":1177941,"num_slots":1,"text":"It’s probably just as well.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1177941,"end_time_ms":1179391,"num_slots":1,"text":"Yeah and you know what?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1179391,"end_time_ms":1189255,"num_slots":1,"text":"I’m happy about it, because you know I just- I think I got a really good experience at Florida.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1189255,"end_time_ms":1191049,"num_slots":1,"text":"Um I have no regrets.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1191049,"end_time_ms":1193963,"num_slots":1,"text":"Um it’s good.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1193963,"end_time_ms":1197074,"num_slots":1,"text":"Did you consider any historically -Black colleges in- in Florida?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1197074,"end_time_ms":1200956,"num_slots":1,"text":"Um no uh—well, let’s see.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1200956,"end_time_ms":1204153,"num_slots":1,"text":"Well, you know I’m from Daytona, so there’s Bethune-Cookman there.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1204153,"end_time_ms":1209281,"num_slots":1,"text":"But very few kids want to go school in their home town.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1209281,"end_time_ms":1211561,"num_slots":1,"text":"I wanted to get out of town, so.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1211561,"end_time_ms":1228495,"num_slots":1,"text":"Um and I don’t know, Florida A&M never uh interested me, although my friends- a lot- went to uh Florida A&M, a lot of them went to Bethune, some of them went to, like, Spelman, and different colleges in Atlanta and Tennessee and","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1228495,"end_time_ms":1232597,"num_slots":1,"text":"all those things, but I- I, you know.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1232597,"end_time_ms":1234695,"num_slots":1,"text":"No, I didn’t consider any of them .","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1234695,"end_time_ms":1250050,"num_slots":1,"text":"But once I got- I was settled on the idea of junior college, and I said, “Hey, if I go to junior college,” I figured out, “then I can go to UF you know or FSU you know as a transfer student.”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1250050,"end_time_ms":1251250,"num_slots":1,"text":"So I said, “Okay, that’s good.”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1251250,"end_time_ms":1254586,"num_slots":1,"text":"I knew that my aunt was- I knew that my aunt was over here.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1254586,"end_time_ms":1262465,"num_slots":1,"text":"And I said, “Okay, that’s close to home, so they can’t say anything about, ‘Oh, we can’t get you home,’ because I can catch a ride home.”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1262465,"end_time_ms":1265065,"num_slots":1,"text":"And in fact, many times I did.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1265065,"end_time_ms":1266721,"num_slots":1,"text":"I caught rides with people.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1266721,"end_time_ms":1278090,"num_slots":1,"text":"Um there was a board in um the student union building where they could post, you know, “I’m going such and such, anybody want a ride?”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1278090,"end_time_ms":1282930,"num_slots":1,"text":"And I would go and look on that board, and you know it worked out.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1282930,"end_time_ms":1288647,"num_slots":1,"text":"And I- I met people who were- were from Daytona I never knew, but I had made their acquaintance .","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1288647,"end_time_ms":1291123,"num_slots":1,"text":"And it turned out to be a win-win deal.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1291123,"end_time_ms":1292315,"num_slots":1,"text":"Yeah.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1292315,"end_time_ms":1300045,"num_slots":1,"text":"Later on, some of my teachers came over here for a master’s, and I would go home with them —you know, in my senior year.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1300045,"end_time_ms":1303463,"num_slots":1,"text":"So, it was good. It was good, yeah.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1303463,"end_time_ms":1303870,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1303870,"end_time_ms":1311582,"num_slots":1,"text":"So my daughter, um when she was a baby uh, I always —I brainwashed her.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1311582,"end_time_ms":1313650,"num_slots":1,"text":"Into being a Gator? Gator Nation?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1313650,"end_time_ms":1321950,"num_slots":1,"text":"Into being a Gator, because that\'s all she ever heard when she was—I married someone here locally, but um divorced early in her life.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1321950,"end_time_ms":1330840,"num_slots":1,"text":"But she came over here constantly for different holidays and in the summer, and she would always be brought out here to Gator stuff.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1330840,"end_time_ms":1333329,"num_slots":1,"text":"And she has a cousin who’s a cheerleader.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1333329,"end_time_ms":1337389,"num_slots":1,"text":"Robin Griffin, who was a cheerleader in the 80s.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1337389,"end_time_ms":1340339,"num_slots":1,"text":"Uh went here, you know, got a degree from here.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1340339,"end_time_ms":1341916,"num_slots":1,"text":"Would bring her out here.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1341916,"end_time_ms":1345766,"num_slots":1,"text":"And uh her father would bring her out here to watch the scrimmages and all that kind of stuff.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1345766,"end_time_ms":1351259,"num_slots":1,"text":"So she was a Gator way before she really had a chance to make a-!","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1351259,"end_time_ms":1352209,"num_slots":1,"text":"She didn’t have a chance.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1352209,"end_time_ms":1353459,"num_slots":1,"text":"No, she didn’t have a chance.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1353459,"end_time_ms":1355190,"num_slots":1,"text":"And did she enjoy her stay here?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1355190,"end_time_ms":1357266,"num_slots":1,"text":"Yes, she had a very different experience.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1357266,"end_time_ms":1357937,"num_slots":1,"text":"She enjoyed it.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1357937,"end_time_ms":1363344,"num_slots":1,"text":"I was going to ask you; what- did you guys have a chance to talk about the different, your experiences here at UF?","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1363344,"end_time_ms":1364454,"num_slots":1,"text":"And the changes?","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1364454,"end_time_ms":1367264,"num_slots":1,"text":"Aside from boys in the restroom?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1367264,"end_time_ms":1377743,"num_slots":1,"text":"Well um, now she- she- she felt like, honest to goodness, that the system was hostile.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1377743,"end_time_ms":1379154,"num_slots":1,"text":"Uh-huh.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1379154,"end_time_ms":1382485,"num_slots":1,"text":"She said they\'re out to flunk you day one!","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1382485,"end_time_ms":1385964,"num_slots":1,"text":"Was that because she’s Black, or just because that’s the way teachers always treat students?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1385964,"end_time_ms":1389584,"num_slots":1,"text":"Not because she was Black, but because they’re trying to weed people out.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1389584,"end_time_ms":1390854,"num_slots":1,"text":"What was her major?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1390854,"end_time_ms":1395194,"num_slots":1,"text":"She um- well, when she first came, she was thinking about Business.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1395194,"end_time_ms":1396594,"num_slots":1,"text":"Then it was Physical Therapy.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1396594,"end_time_ms":1399678,"num_slots":1,"text":"She finally majored in Speech Pathology.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1399678,"end_time_ms":1401488,"num_slots":1,"text":"Oh, interesting.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1401488,"end_time_ms":1403567,"num_slots":1,"text":"Turned out to be a very good choice.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1403567,"end_time_ms":1405238,"num_slots":1,"text":"Very good choice.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1405238,"end_time_ms":1408558,"num_slots":1,"text":"Um next week, she’s opening her own clinic.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1408558,"end_time_ms":1409686,"num_slots":1,"text":"Oh, good for her!","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1409686,"end_time_ms":1412618,"num_slots":1,"text":"Yeah. So, that- that was very productive.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1412618,"end_time_ms":1415108,"num_slots":1,"text":"But she found the teachers hostile.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1415108,"end_time_ms":1420528,"num_slots":1,"text":"It wasn\'t- It wasn’t that this one per se, it’s the system.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1420528,"end_time_ms":1421150,"num_slots":1,"text":"Oh, I see.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1421150,"end_time_ms":1422318,"num_slots":1,"text":"The system.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1422318,"end_time_ms":1426168,"num_slots":1,"text":"She said it\'s- it’s very- it\'s very cold .","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1426168,"end_time_ms":1427510,"num_slots":1,"text":"Cold and impersonal.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1427510,"end_time_ms":1435128,"num_slots":1,"text":"Um...It’s, like, set up to knock so many kids out, you know, the freshman year.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1435128,"end_time_ms":1442139,"num_slots":1,"text":"You kinda weed it down so that um by the time they have to choose a college, they have fewer people to deal with.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1442139,"end_time_ms":1445452,"num_slots":1,"text":"But she- she found it an unfriendly system.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1445452,"end_time_ms":1448778,"num_slots":1,"text":"But, you know, she prospered.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1448778,"end_time_ms":1450758,"num_slots":1,"text":"She did fine.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1450758,"end_time_ms":1454288,"num_slots":1,"text":"Um, she- she got her bachelor ’s.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1454288,"end_time_ms":1462707,"num_slots":1,"text":"She was- just- just got started to get over the fact that she wasn\'t admitted to grad school.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1462707,"end_time_ms":1464497,"num_slots":1,"text":"She was really POed about that.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1464497,"end_time_ms":1466960,"num_slots":1,"text":"She said, “I’m one of their own.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1466960,"end_time_ms":1469266,"num_slots":1,"text":"I didn’t come here from someplace else.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1469266,"end_time_ms":1471357,"num_slots":1,"text":"I came here as a freshman.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1471357,"end_time_ms":1480276,"num_slots":1,"text":"I duked it out that whole time, you know, got my degree; I should’ ve been given priority, not somebody from Kalamazoo.”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1480276,"end_time_ms":1490117,"num_slots":1,"text":"And I don’t know, I think they have reasons for letting other people in, and sending most of their kids other places.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1490117,"end_time_ms":1497927,"num_slots":1,"text":"I’m not sure what it all abouts, but, you know I always- it was a very uneasy time.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1497927,"end_time_ms":1502547,"num_slots":1,"text":"But she received her master’s from Howard University, which is a Black school.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1502547,"end_time_ms":1504567,"num_slots":1,"text":"And a very good school.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1504567,"end_time_ms":1507397,"num_slots":1,"text":"Yeah, I’m from the D .C.-Baltimore area, so I’m familiar with Howard.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1507397,"end_time_ms":1513192,"num_slots":1,"text":"Yeah. And what I- what I said to her was, you know, it was divine intervention.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1513192,"end_time_ms":1518657,"num_slots":1,"text":"It was your opportunity to see the best of both worlds, and you’re the better for it.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1518657,"end_time_ms":1522067,"num_slots":1,"text":"And she did. She said it was a different atmosphere there.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1522067,"end_time_ms":1529342,"num_slots":1,"text":"It was a more loving atmosphere, it was a smaller, uh just warm, “I’ll help you ,” fuzzy kind of thing.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1529342,"end_time_ms":1530422,"num_slots":1,"text":"Well, you’re in the big city.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1530422,"end_time_ms":1538405,"num_slots":1,"text":"Right. But, she said, “If you can make it at Florida, you can make it at anywhere, make it anywhere.”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1538405,"end_time_ms":1543367,"num_slots":1,"text":"Because she said you’re on your own at Florida!","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1543367,"end_time_ms":1553192,"num_slots":1,"text":"So, you know I said it was just in preparation for what you needed to do in graduate school, which was to work all day for a grade and then go to classes at night.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1553192,"end_time_ms":1554652,"num_slots":1,"text":"And so, she did well.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1554652,"end_time_ms":1573052,"num_slots":1,"text":"Uh, she’s had um managerial jobs, um she was able to move all about the country, you know um working in um geriatric- with the geriatric populations —which is what she prefers, but you know she could work at schools or whatever.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1573052,"end_time_ms":1587096,"num_slots":1,"text":"Um a year ago, she and three- um two other ladies formed a company for speech and language services, and so they’ re opening their clinic uh after one year, uh this week, and they\'ve—","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1587096,"end_time_ms":1588061,"num_slots":1,"text":"Congratulations to her.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1588061,"end_time_ms":1595461,"num_slots":1,"text":"—Really extended their clientele to uh early uh intervention, uh geriatric, as well as schools.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1595461,"end_time_ms":1596801,"num_slots":1,"text":"So…","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1596801,"end_time_ms":1607175,"num_slots":1,"text":"Just to- to move to the social area, you said you- you felt —um I forget your exact words, but you said something about, you know no one invited you join anything, it was very cold socially, at least that\'s what your.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1607175,"end_time_ms":1607571,"num_slots":1,"text":"Right.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1607571,"end_time_ms":1611742,"num_slots":1,"text":"Did she notice anything different when she was here, some thirty-some-odd years later?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1611742,"end_time_ms":1621726,"num_slots":1,"text":"Um she- she really didn’t comment on- on it, but she never said that she was invited to join anything.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1621726,"end_time_ms":1627106,"num_slots":1,"text":"And I don’t think she did join anything.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1627106,"end_time_ms":1632749,"num_slots":1,"text":"Um it was basically going to class. She got a job, she worked at the library.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1632749,"end_time_ms":1636310,"num_slots":1,"text":"Same thing that I did, uh worked in the library.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1636310,"end_time_ms":1643213,"num_slots":1,"text":"At one point she was working at —I don’t know, maybe working for SGA or something in the reception area.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1643213,"end_time_ms":1647310,"num_slots":1,"text":"Um worked different little jobs along the way.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1647310,"end_time_ms":1649694,"num_slots":1,"text":"But, she didn’t make a comment.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1649694,"end_time_ms":1650930,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1650930,"end_time_ms":1653214,"num_slots":1,"text":"Well, I’m pretty much done.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1653214,"end_time_ms":1658417,"num_slots":1,"text":"Um…you’ve covered all my questions, even without me asking them, so that’s a beautiful thing.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1658417,"end_time_ms":1666380,"num_slots":1,"text":"Um…so, if you have anything else you maybe wanted to mention here about your life at Florida, or your involvement with this organization?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1666380,"end_time_ms":1676481,"num_slots":1,"text":"Um…the- the only thing, I’ve been a little POed, and I’m not exactly who to aim- aim- sure who to aim it at.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1676481,"end_time_ms":1686688,"num_slots":1,"text":"But, okay: this is my third year coming to this particular activity, but when announcements or when the cards are sent out about it, they send them to my daughter.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1686688,"end_time_ms":1689290,"num_slots":1,"text":"In your name?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1689290,"end_time_ms":1691777,"num_slots":1,"text":"No, they just send them to my daughter.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1691777,"end_time_ms":1693820,"num_slots":1,"text":"Because you know she was a student here, too.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1693820,"end_time_ms":1695854,"num_slots":1,"text":"It’s like they don’t know I’m living.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1695854,"end_time_ms":1701970,"num_slots":1,"text":"And I- and every year, I fill out some papers, and I’m saying, “Okay, what’s going on here?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1701970,"end_time_ms":1704411,"num_slots":1,"text":"Is somebody asleep on the job?”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1704411,"end_time_ms":1713589,"num_slots":1,"text":"And then, uh also, I found out that the College of Education had some kind of activity at the president’s house uh yesterday.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1713589,"end_time_ms":1718149,"num_slots":1,"text":"I received no notice about that, and both of my degrees are in Education.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1718149,"end_time_ms":1723908,"num_slots":1,"text":"And so…Right. And my niece received one, the one that was a former cheerleader.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1723908,"end_time_ms":1731724,"num_slots":1,"text":"And um my friend received another notice for I think October, for Homecoming, about some other activity.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1731724,"end_time_ms":1737889,"num_slots":1,"text":"And I’m going, “Okay, uh I know they have my name somewhere, because they send me the publications and other things.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1737889,"end_time_ms":1739678,"num_slots":1,"text":"So, what is the deal?”","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1739678,"end_time_ms":1740564,"num_slots":1,"text":"Yeah, I don’t know.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1740564,"end_time_ms":1743934,"num_slots":1,"text":"I don’t know much about the organization but that’s certainly something you need to look into.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1743934,"end_time_ms":1745984,"num_slots":1,"text":"So, I need to get to the bottom of that.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1745984,"end_time_ms":1748668,"num_slots":1,"text":"Yeah. That’s one of the drawbacks of a big school.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1748668,"end_time_ms":1750524,"num_slots":1,"text":"Yeah a lot of- A lot of paperwork.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1750524,"end_time_ms":1764184,"num_slots":1,"text":"One other thing that concerns me: the number of friends that I know that —and people that I met —that say, “ I’m a Florida graduate, I’m a Gator ,” but they don’t- they don\'t come here.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1764184,"end_time_ms":1766444,"num_slots":1,"text":"They don’t do this.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1766444,"end_time_ms":1772364,"num_slots":1,"text":"They don’t —I realize getting a ticket to the game is hard, but they don’t try to come back to the university .","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1772364,"end_time_ms":1775294,"num_slots":1,"text":"And I don’t quite understand what the dynamics —.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1775294,"end_time_ms":1779624,"num_slots":1,"text":"Do you mean as part of the Association of Black Alumni, or just in general as active alumni?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1779624,"end_time_ms":1782381,"num_slots":1,"text":"In general, as anything.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1782381,"end_time_ms":1784414,"num_slots":1,"text":"And, I don’t know.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1784414,"end_time_ms":1792134,"num_slots":1,"text":"When I talk to some of them, some of them express the feeling of being maybe ostracized or left out .","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1792134,"end_time_ms":1796529,"num_slots":1,"text":"And, “Yeah, I went to school there, but I don’t see anything —.”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1796529,"end_time_ms":1807673,"num_slots":1,"text":"Whatever. And I don’t know, I don’t understand that because I said well you know, I went to school there, too; and even though I didn’t belong to a club and stuff, I still know that I’m a Gator .","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1807673,"end_time_ms":1815309,"num_slots":1,"text":"And I still love being in Gainesville, I love being on campus, and I think about all the happy things that happened to me there.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1815309,"end_time_ms":1820473,"num_slots":1,"text":"And I said, did somebody beat you across the head, or hurt your feelings or something?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1820473,"end_time_ms":1822983,"num_slots":1,"text":"You know? But I don’t know.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1822983,"end_time_ms":1825923,"num_slots":1,"text":"It’s- It\'s some kind of feeling, and I don’t know how to get —","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1825923,"end_time_ms":1827553,"num_slots":1,"text":"Yeah. Some people are just affected it differently.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1827553,"end_time_ms":1828203,"num_slots":1,"text":"Or not affected.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1828203,"end_time_ms":1829013,"num_slots":1,"text":"Right.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1829013,"end_time_ms":1834373,"num_slots":1,"text":"And so, it saddens me, because I\'m looking around I\'m saying, “Okay, where are the people from my generation?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1834373,"end_time_ms":1835853,"num_slots":1,"text":"I’d like to see them.”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1835853,"end_time_ms":1839392,"num_slots":1,"text":"You know. I’ve even tried to find some of them on Facebook.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1839392,"end_time_ms":1840294,"num_slots":1,"text":"Oh, really?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1840294,"end_time_ms":1850282,"num_slots":1,"text":"You know. I found one- I found one guy, and um just as I started a little dialogue with him, all of the sudden the curtains came down.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1850282,"end_time_ms":1859608,"num_slots":1,"text":"I don’t know if his um wife, or I don’t know what happened; but all of the sudden, he started- I started to see more details about the family.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1859608,"end_time_ms":1860644,"num_slots":1,"text":"I say, “Okay, that’s fine.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1860644,"end_time_ms":1863458,"num_slots":1,"text":"All I want to know is, have you talked to So-and-so?","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1863458,"end_time_ms":1866328,"num_slots":1,"text":"You know. Have you seen any of our old crowd?”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1866328,"end_time_ms":1870593,"num_slots":1,"text":"But I didn’t- I didn\'t get too far on that because, you know…","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1870593,"end_time_ms":1872806,"num_slots":1,"text":"Yeah. It can be a hit and miss.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1872806,"end_time_ms":1874249,"num_slots":1,"text":"I’m on Facebook, too.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1874249,"end_time_ms":1874914,"num_slots":1,"text":"It can be—","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1874914,"end_time_ms":1878141,"num_slots":1,"text":"I get in touch with people I haven’t seen since high school.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1878141,"end_time_ms":1879233,"num_slots":1,"text":"Yeah, that’s the beauty of it!","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1879233,"end_time_ms":1880951,"num_slots":1,"text":"And I was saying, “Oh, boy!","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1880951,"end_time_ms":1884392,"num_slots":1,"text":"Now I can find out what happened to all of those guys.”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1884392,"end_time_ms":1901247,"num_slots":1,"text":"But you know, one guy that was very um uh very active socially here, um I found him at the University of California at Northridge; he’s a professor there.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1901247,"end_time_ms":1906490,"num_slots":1,"text":"He’s a uh very um uh—he’s a social activist .","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1906490,"end_time_ms":1913075,"num_slots":1,"text":"And I- I found him, emailed him, called him; he called me back.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1913075,"end_time_ms":1918521,"num_slots":1,"text":"We had a conversation- about a three hour conversation on the phone one day, and then I never heard from him again.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1918521,"end_time_ms":1921620,"num_slots":1,"text":"I tried to beep him again, say, “Okay.”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1921620,"end_time_ms":1925532,"num_slots":1,"text":"Because I keep saying, “You don’t come to the reunions; come to the reunions.”","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1925532,"end_time_ms":1929102,"num_slots":1,"text":"But it’s been a few months now, and I haven’t heard from him, so.","dependents":[]},{"speaker":"S1","tier":"Diana Bell","start_time_ms":1929102,"end_time_ms":1929482,"num_slots":1,"text":"I don’t know.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1929482,"end_time_ms":1930142,"num_slots":1,"text":"Well, thank you very much.","dependents":[]},{"speaker":"S2","tier":"Interviewer","start_time_ms":1930142,"end_time_ms":1931716,"num_slots":1,"text":"I’m going to go ahead and stop this.","dependents":[]}]}')}}]);
//# sourceMappingURL=23.bundle.js.map